#!/usr/bin/env bash
# QC (X187-X189): share cross-check rules, OWNERS_BEFORE_JV_SHARE, and resolutions of filer errors.
# Ids are from the snapshot of 2026-11-17; a resolve of an id that is already closed fails harmlessly (set +e).
set -u
PY="${PY:-python}"
D="${D:-data}"

# 1. X189 (parser 0.10.6 after merge): re-parse results filings with open parse / identity / period findings, then promote.
#    promote also re-runs the share cross-check (X187 split/bonus after period end, X188 whole-unit paid-up,
#    zero paid-up) and closes the agreeing CROSS_CHECK_FAILED findings (expected 27 of 275; 16 ATTRIBUTION_WITHHELD).
$PY -m financials --data-dir "$D" restage --category RESULTS_XBRL
$PY -m financials --data-dir "$D" promote

set +e
